209	// Joined as the newest socket on the session, which carries this upgrade's credentials from here on.
210	function join(session: ChatSession, ws: ExtWebSocket): void {
211	  openSockets.set(session, [...(openSockets.get(session) ?? []), ws]);
212	  session.authHeaders = ws.authHeaders;
213	}
214	
215	// `undefined` rather than a throw: one store failure closes one socket instead of ending the process.
216	async function createSession(
217	  deps: ConnectionHandlerDeps,
218	  sessionId: string,
219	  ws: ExtWebSocket
220	): Promise<ChatSession | undefined> {
221	  try {
222	    return await deps.sessionStore.create(sessionId, ws.userId, {
223	      authHeaders: ws.authHeaders,
224	      workspaceId: ws.workspaceId,
225	    });
226	  } catch (error) {
227	    log.error('ws', 'session create failed', {userId: ws.userId, error: messageOf(error)});
228	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not start a session');
229	    return undefined;
230	  }
231	}
232	
233	// The close path erases nothing: the conversation outlives its socket, and `onDisconnect` is the consumer's seam.
234	function endSession(
235	  deps: ConnectionHandlerDeps,
236	  sessionId: string,
237	  state: {notified: boolean; delivered: boolean},
238	  held: {session?: ChatSession; socket: ExtWebSocket}
239	): void {
240	  if (state.notified) return;
241	  state.notified = true;
242	
243	  if (held.session) leave(held.session, held.socket);
244	
245	  // Only for a session the consumer was actually handed: onDisconnect is the other half of onConnect, not of a socket.
246	  if (!state.delivered) return;
247	
248	  runHook('onDisconnect', sessionId, () => deps.onDisconnect?.(sessionId));
249	}
250	
251	// The newest socket still open lends the session its credentials; with none left, nothing keeps them or a closed socket.
252	function leave(session: ChatSession, ws: ExtWebSocket): void {
253	  const open = openSockets.get(session) ?? [];
254	  if (!open.includes(ws)) return;
255	  const remaining = open.filter(socket => socket !== ws);
256	  const newest = remaining.at(-1);
257	  if (newest === undefined) {
258	    openSockets.delete(session);
259	    session.authHeaders = undefined;
260	    return;
261	  }
262	  openSockets.set(session, remaining);
263	  session.authHeaders = newest.authHeaders;
264	}
265	
266	// Never a resumed session: evict erases, and a resumed session holds the conversation being rejoined.
267	async function evictUnlessResumed(
268	  deps: ConnectionHandlerDeps,
269	  sessionId: string,
270	  resumed: ChatSession | undefined
271	): Promise<void> {
272	  if (!resumed) await evictSession(deps, sessionId);
273	}
274	
275	// Only for a session no client ever received: it has no entries and nothing to migrate.
276	async function evictSession(deps: ConnectionHandlerDeps, sessionId: string): Promise<void> {
277	  try {
278	    await deps.sessionStore.evict?.(sessionId);
279	  } catch (error) {
280	    log.error('ws', 'session evict failed', {sessionId, error: messageOf(error)});
281	  }
282	}
283	
284	// Consumer hooks are fire-and-forget: the engine never awaits one and never lets one take the connection down.
285	function runHook(name: string, sessionId: string, call: () => void | Promise<void>): void {
286	  try {
287	    // Promise.resolve also absorbs a thenable from another realm, where `instanceof Promise` is false.
288	    void Promise.resolve(call()).catch((error: unknown) => logHookFailure(name, sessionId, error));
289	  } catch (error) {
290	    logHookFailure(name, sessionId, error);
291	  }
292	}
293	
294	function logHookFailure(name: string, sessionId: string, error: unknown): void {
295	  log.error('ws', `${name} hook failed`, {sessionId, error: messageOf(error)});
296	}
297	
298	function messageOf(error: unknown): string {
299	  if (typeof error === 'object' && error !== null && 'message' in error) return String(error.message);
300	  return String(error);
301	}
