function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 1 || message.limit > 200) {
      return {valid: false, error: 'limit must be an integer between 1 and 200'};
    }
  }

  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;
    if (typeof before !== 'object' || before === null) {
      return {valid: false, error: 'before must be a cursor object with updatedAt and sessionId'};
    }
    if (typeof before.sessionId !== 'string') {
      return {valid: false, error: 'before must have a sessionId string'};
    }
    if (typeof before.updatedAt !== 'string' || !Number.isFinite(Date.parse(before.updatedAt))) {
      return {valid: false, error: 'before.updatedAt must be a valid date string'};
    }
    return {
      valid: true,
      data: {
        type: 'list_conversations',
        ...(message.limit !== undefined ? {limit: message.limit as number} : {}),
        before: {updatedAt: before.updatedAt as string, sessionId: before.sessionId},
      },
    };
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      ...(message.limit !== undefined ? {limit: message.limit as number} : {}),
    },
  };
}

